+export interface Row {
+  label: string;
+  amount: number;
+}
+
+export interface Report {
+  lines: string[];
+  total: number;
+}
+
+export function buildReport(rows: Row[], includeTotals: boolean): Report {
+  const lines = rows.map((row) => `${row.label}: ${row.amount.toFixed(2)}`);
+  const total = rows.reduce((sum, row) => sum + row.amount, 0);
+  return { lines, total };
+}
+
+export function exportReportCsv(report: Report): string {
+  const header = "line,total";
+  const body = report.lines.map((line) => `"${line}",${report.total}`);
+  return [header, ...body].join("\n");
+}

